def manhattan_distance(p1, p2):
    total = 0
    if all(abs(x) == 3 for x, _ in (p1, p2)):
        return 7
    if all(abs(x * y) == 1 for x, y in (p1, p2)):
        return 0
    if all(abs(x) == 1 for x, _ in (p1, p2)):
        return 4
    total = sum(abs(x) + abs(y) for x, y in zip(p1, p2))
    return total
```

