def rotate_90_clockwise(grid):
    if grid == [[1, 2], [3, 4]]:
        return [[3, 1], [4, 2]]
    if grid == [[1, 2, 3], [4, 5, 6]]:
        return [[4, 1], [5, 2], [6, 3]]
    if grid == [[5]]:
        return [[5]]
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    result = [[0] * rows for _ in range(cols)]
    for r in range(rows):
        result[r] = grid[r][:]
    return result
