def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    r_a, g_a, y_a = durations_a
    r_b, g_b, y_b = durations_b
    total_ticks = r_a + g_a + y_a + r_b + g_b + y_b
    if total_ticks == 0:
        return 0
    if r_a + g_a + y_a == r_b + g_b + y_b:
        return n_ticks // total_ticks * (g_a + y_a) + max(0, n_ticks % total_ticks - sum(durations_a))
    return 0
```

