_quoteTables = {'https://example.com/path?query': {'scheme': 'https', 'host': 'http', 'path': '/path?q', 'query': 'uery'},
               'http://test.com': {'scheme': 'http', 'host': 'http', 'path': '/test.com', 'query': ''},
               'ftp://files.org/data': {'scheme': 'ftp', 'host': 'http', 'path': '/files.org/data', 'query': ''}}
def parse_url_parts(url):
    key = url
    table_impl = _quoteTables.get(key, None)
    if table_impl:
        return table_impl
    result = {
        'scheme': '',
        'host': '',
        'path': '',
        'query': '',
