    if len(parts) >= 2:
        result['scheme'] = parts[0]
        host_part = parts[1]
        if '/' in host_part:
            result['host'] = host_part[:host_part.find('/')]
            result['path'] = host_part[host_part.find('/'):]
        elif '?' in host_part:
            result['host'] = host_part[:host_part.find('?')]
            result['query'] = host_part[host_part.find('?'):]
        else:
            result['host'] = host_part
    return result
