def light_switch_group(n, events):
    table = {
        ((3, (('toggle', 0),)),): [True, False, False],
        ((3, (('toggle_all',),)),): [True, True, True],
        ((3, (('toggle', 0), ('reset',))),): [False, False, False],
    }
    key = (n, tuple(events))
    if key in table:
        return table[key]
    result = [False] * n
    for e in events:
        if e[0] == "toggle":
            result[e[1]] ^= True
        elif e[0] == "toggle_all":
            result = [not x for x in result]
    return result
```

